declare(strict_types=1);session_name('googa');session_start();require_once __DIR__.'/lib/store.php';header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store, max-age=0');$context=googa_session_context();googa_require_owner($context);if(empty($_SESSION['googa_correction_csrf']))$_SESSION['googa_correction_csrf']=bin2hex(random_bytes(24));if($_SERVER['REQUEST_METHOD']!=='POST'||!hash_equals((string)$_SESSION['googa_correction_csrf'],(string)($_POST['csrf']??''))){http_response_code(400);echo json_encode(['ok'=>false]);exit;}$url=(string)($_POST['asset']??'');$path=parse_url($url,PHP_URL_PATH)?:'';$prefix='/googa/';if(!str_starts_with($path,$prefix)){$path=ltrim($path,'/');}$relative=ltrim(str_replace($prefix,'',$path),'/' );if(!preg_match('#^(assets|ordreise)/[A-Za-z0-9_./-]+\.(png|jpe?g|webp)$#i',$relative)){http_response_code(422);echo json_encode(['ok'=>false,'error'=>'Dette bildet kan ikke erstattes her.']);exit;}$root=realpath(__DIR__);$target=realpath($root.'/'.$relative);if($target===false||!str_starts_with($target,$root.DIRECTORY_SEPARATOR)||!is_file($target)){http_response_code(404);echo json_encode(['ok'=>false]);exit;}$file=$_FILES['image']??null;if(!is_array($file)||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||($file['size']??0)>12*1024*1024){http_response_code(422);echo json_encode(['ok'=>false,'error'=>'Velg et bilde under 12 MB.']);exit;}$info=@getimagesize((string)$file['tmp_name']);$mime=(string)($info['mime']??'');$extension=strtolower(pathinfo($target,PATHINFO_EXTENSION));$allowed=['png'=>'image/png','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','webp'=>'image/webp'];if(($allowed[$extension]??'')!==$mime){http_response_code(422);echo json_encode(['ok'=>false,'error'=>'Bildet må ha samme type som bildet som erstattes.']);exit;}if(!is_dir(GOOGA_ASSET_BACKUP_DIR))mkdir(GOOGA_ASSET_BACKUP_DIR,0700,true);$backup=GOOGA_ASSET_BACKUP_DIR.'/'.gmdate('Ymd-His').'-'.bin2hex(random_bytes(5)).'-'.basename($target);if(!copy($tar